// Matrix Chain Multiplication - canonical interval DP
// p: dimensions array where matrix i has size p[i-1] x p[i]
function matrixChainOrder(p) {
  const n = p.length - 1; // number of matrices
  // dp[i][j] = min multiplications for matrices i..j (1-indexed)
  const dp = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(0));

  // base case: dp[i][i] = 0 (single matrix, already set to 0)

  // fill by increasing interval length
  for (let len = 2; len <= n; len++) {
    for (let i = 1; i <= n - len + 1; i++) {
      const j = i + len - 1;
      dp[i][j] = Infinity;

      // try every split point k
      for (let k = i; k < j; k++) {
        const cost = dp[i][k] + dp[k + 1][j] + p[i - 1] * p[k] * p[j];
        dp[i][j] = Math.min(dp[i][j], cost);
      }
    }
  }

  return dp[1][n]; // min cost for full chain
}
